terraform.main.tf:
provider "aws" {}

resource "aws_lambda_function" "create_item" {
  filename         = "create_item.zip"
  function_name    = "create_item"
  role             = aws_iam_role.lambda_role.arn
  handler          = "create_item.handler"
  runtime          = "python3.8"
  source_code_hash = filebase64sha256("create_item.zip")
}

resource "aws_iam_role" "lambda_role" {
  name = "lambda_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_lambda_permission" "allow_api_gateway" {
  statement_id  = "AllowExecutionFromAPIGateway"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.create_item.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "*"
}

terraform.variables.tf:
variable "region" {
  description = "The AWS region where the resources will be created"
  type        = string
}

variable "table_name" {
  description = "The name of the DynamoDB table"
  type        = string
}

python.create_item.py:
import json
import boto3
from botocore.exceptions import ClientError

def handler(event, context):
    dynamodb = boto3.resource('dynamodb', region_name=event['region'])
    table = dynamodb.Table(event['table_name'])

    try:
        response = table.put_item(
            Item=event['item']
        )
        return json.dumps({'statusCode': 200, 'body': json.dumps(response)})
    except ClientError as e:
        return json.dumps({'statusCode': 500, 'body': json.dumps(e.response)})

